// Read all registers in parallel
const reads = [
    { name: 'deviceType', address: 100, quantity: 1 },
    { name: 'serialNumber', address: 103, quantity: 5 },
    { name: 'firmware', address: 114, quantity: 5 },  // 114-118
    { name: 'ratedPower', address: 120, quantity: 2 },  // 120-121 (32-bit)
    { name: 'gridStandard', address: 282, quantity: 1 },
    { name: 'gridFrequency', address: 283, quantity: 1 },
    { name: 'voltageLevel', address: 238, quantity: 1 },
    { name: 'phaseSequence', address: 247, quantity: 1 },
    { name: 'batteryMode', address: 211, quantity: 1 },
    { name: 'batteryCapacity', address: 202, quantity: 1 },
    { name: 'genInputMode', address: 233, quantity: 1 },
    { name: 'genConnectedGrid', address: 289, quantity: 1 },
    { name: 'exportLimitMode', address: 242, quantity: 1 }
];

const messages = reads.map(r => ({
    payload: {
        fc: 3,
        unitid: 1,
        address: r.address,
        quantity: r.quantity
    },
    readName: r.name
}));

return [messages];

const flowKey = 'scs_reads';
let collected = flow.get(flowKey) || {};
let expectedCount = 13;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 1) {
    node.status({ fill: "red", shape: "dot", text: "Read failed: " + msg.readName });
    return null;
}

const readName = msg.readName;

// Store the data based on type
if (readName === 'serialNumber' || readName === 'firmware' || readName === 'ratedPower') {
    // Multi-register reads - store array
    collected[readName] = data;
} else {
    // Single register reads
    collected[readName] = data[0];
}

flow.set(flowKey, collected);

const collectedCount = Object.keys(collected).length;
node.status({ fill: "blue", shape: "dot", text: `Collected ${collectedCount}/${expectedCount}` });

if (collectedCount >= expectedCount) {
    flow.set(flowKey, null);
    msg.collectedData = collected;
    msg.payload = collected;
    return msg;
}

return null;

const data = msg.collectedData;

if (!data) {
    node.status({ fill: "red", shape: "dot", text: "No data" });
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

// Parse Serial Number (5 registers = 10 ASCII)
function parseSerialNumber(regs) {
    let sn = "";
    for (let i = 0; i < regs.length; i++) {
        const highByte = (regs[i] >> 8) & 0xFF;
        const lowByte = regs[i] & 0xFF;
        sn += String.fromCharCode(highByte);
        sn += String.fromCharCode(lowByte);
    }
    return sn.replace(/\0/g, '').trim();
}

const serialNumber = parseSerialNumber(data.serialNumber);

// Parse device type and derive model
const deviceType = data.deviceType;
let inverterModel = "Unknown";
if (deviceType === 0x03) inverterModel = "Single-phase LV hybrid";
else if (deviceType === 0x05) inverterModel = "Three-phase LV hybrid";
else if (deviceType === 0x06) inverterModel = "Three-phase HV hybrid";

const gridPhaseCount = (deviceType === 0x05 || deviceType === 0x06) ? 3 : 1;

// Parse firmware versions
const fw = data.firmware;
const firmware = {
    protocolVersion: null,
    mcuBoardRaw: null,
    controlHardwareRaw: fw[0],  // 114
    controlMainRaw: fw[1],      // 115
    commField1Raw: fw[2],       // 116
    commField2Raw: fw[3],       // 117
    commMainRaw: fw[4]          // 118
};

// Parse rated power (32-bit: low word + high word)
const ratedPowerRaw = (data.ratedPower[1] << 16) | data.ratedPower[0];
const ratedPowerW = ratedPowerRaw / 10;  // 0.1W scale

// Parse grid frequency
const gridFrequencyHz = data.gridFrequency === 0 ? 50 : 60;

// Parse grid phase sequence
const gridPhaseSequence = data.phaseSequence === 0 ? "ABC_0_120_240" : "ACB_0_240_120";

// Parse battery control mode
const batteryModeMap = {
    0: "voltage",
    1: "capacity",
    2: "no_battery"
};
const batteryControlMode = batteryModeMap[data.batteryMode] || "no_battery";

// Parse generator input mode
const genInputModeMap = {
    0: "generator_input",
    1: "smart_load",
    2: "micro_inverter_input"
};
const genInputMode = genInputModeMap[data.genInputMode] || "generator_input";

// Parse export limit mode
const exportLimitModeMap = {
    0x00: "sell_enabled",
    0x01: "internal_meter",
    0x02: "external_ct"
};
const exportLimitMode = exportLimitModeMap[data.exportLimitMode] || "sell_enabled";

// Build the complete structure
const structure = {
    kind: "SystemConnectionStructure",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: gatewayId,
    schemaVersion: 1,

    inverter: {
        deviceType: deviceType,
        inverterModel: inverterModel,
        serialNumber: serialNumber,
        firmware: firmware,
        ratedPowerW: ratedPowerW,

        acSide: {
            mpptAndPhasesRaw: null,
            batteryInputCount: null,
            outputTopology: null,
            gridType: null,
            regionVariant: null,
            safetyTypeRaw: null,
            gridPhaseCount: gridPhaseCount,
            gridStandardRaw: data.gridStandard,
            gridFrequencyHz: gridFrequencyHz,
            gridVoltageLevelCode: data.voltageLevel,
            gridPhaseSequence: gridPhaseSequence,
            itSystemNeutralUngrounded: null
        }
    },

    battery: {
        batteryControlMode: batteryControlMode,
        batteryChannels: [
            {
                channelId: 1,
                ratedCapacityAh: data.batteryCapacity,
                nominalVoltageV: null,
                batterySn: null,
                batteryPhysicalAddress: null,
                batterySoftwareVersion: null,
                lithiumBatteryType: null
            }
        ]
    },

    generator: {
        inputMode: genInputMode,
        connectedToGridInput: data.genConnectedGrid === 1
    },

    pv: {
        mpptCount: null,
        mppt: [
            { pvChannelId: 1, supportsInput: true, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null },
            { pvChannelId: 2, supportsInput: true, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null },
            { pvChannelId: 3, supportsInput: true, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null },
            { pvChannelId: 4, supportsInput: true, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null }
        ]
    },

    loadAndGrid: {
        homeLoadConnectionPoint: null,
        exportLimitMode: exportLimitMode,
        currentTransformerOnGridSide: null,
        supportsBackupLoad: null,
        supportsZeroExport: null,
        supportsExternalMeter: null
    }
};

msg.payload = structure;
msg.state = structure;

node.status({ fill: "green", shape: "dot", text: `${inverterModel} - SN: ${serialNumber}` });

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;
